// Nächste 14 Tage durchgehen und freie 20-Min-Slots finden
// Öffnungszeiten: Mo-Fr 09:00-18:00

const existingEvents = $input.all().map(item => ({
  start: new Date(item.json.start.dateTime || item.json.start.date),
  end: new Date(item.json.end.dateTime || item.json.end.date)
}));

const slots = [];
const now = new Date();
const slotDuration = 20; // Minuten
const maxSlots = 6;

for (let dayOffset = 0; dayOffset < 14 && slots.length < maxSlots; dayOffset++) {
  const day = new Date(now);
  day.setDate(day.getDate() + dayOffset);

  // Nur Mo-Fr (1-5)
  const weekday = day.getDay();
  if (weekday === 0 || weekday === 6) continue;

  // Slots von 09:00 bis 17:40 (letzter 20-Min-Slot endet um 18:00)
  for (let hour = 9; hour < 18 && slots.length < maxSlots; hour++) {
    for (let minute = 0; minute < 60 && slots.length < maxSlots; minute += slotDuration) {
      const slotStart = new Date(day);
      slotStart.setHours(hour, minute, 0, 0);

      const slotEnd = new Date(slotStart);
      slotEnd.setMinutes(slotEnd.getMinutes() + slotDuration);

      // Slot muss vor 18:00 enden
      const endLimit = new Date(day);
      endLimit.setHours(18, 0, 0, 0);
      if (slotEnd > endLimit) continue;

      // Slot muss in der Zukunft liegen
      if (slotStart <= now) continue;

      // Prüfen ob Slot mit bestehendem Termin kollidiert
      const hasConflict = existingEvents.some(event => 
        slotStart < event.end && slotEnd > event.start
      );

      if (!hasConflict) {
        const dayNames = ['Sonntag', 'Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag'];
        slots.push({
          start: slotStart.toISOString(),
          end: slotEnd.toISOString(),
          display: `${dayNames[slotStart.getDay()]}, ${slotStart.toLocaleDateString('de-DE')} um ${slotStart.toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' })} Uhr`
        });
      }
    }
  }
}

return [{ json: { available_slots: slots, count: slots.length } }];
